package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ArtLiveExamAsianArtBank2 {
    private const val T = "පෙරදිග ආසියාතික කලාව (ඉන්දියාව, චීනය, ජපානය)"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("ඉන්දියාවේ මෞර්ය යුගයේ 'බරාබර් ලෙන්' (Barabar Caves) විශේෂ වන්නේ කුමන තාක්ෂණික ගුණාංගය නිසාද?", "දැඩි ග්‍රැනයිට් ගල් බිත්ති කැඩපතක් මෙන් ඔප දමා කපා තිබීම", "වීදුරු ජනෙල් සවි කර තිබීම", "රන් ආලේපිත ලී බිත්ති වීම", "තෙල් සායම් සිතුවම් තිබීම", "අශෝක රජු ආජීවකයන්ට පූජා කළ බරාබර් ලෙන් ඇතුළත කළුගල් පෘෂ්ඨය මෞර්ය ඔපයෙන් දිදුලයි."),
        q("සාංචි මහා ස්තූපයේ කැටයම්වල බහුලව දැකිය හැකි බෞද්ධ පෙර භවයක කතාව නිරූපණය කරන ජාතකය කුමක්ද?", "ඡද්දන්ත ජාතකය හා වෙස්සන්තර ජාතකය", "සීගිරි කතා පුවත", "රෝම ඉතිහාස කතාව", "මහා භාරත ගීතය", "සාංචි තොරණ හරස් දඬුවල ඇත් රජුගේ හා වෙස්සන්තර රජුගේ ජාතක කතා සියුම්ව කැටයම් කර ඇත."),
        q("ඉන්දියාවේ 'භාරුත් ස්තූප' වැටෙහි (Railings) කැටයම් කර ඇති කලා කෘතිවල ප්‍රධාන ලක්ෂණය කුමක්ද?", "පැතලි කැටයමින් ජාතක පදක්කම්", "වටකුරු කිරිගරුඬ ග්‍රීක ප්‍රතිමා", "චීන පෝසිලේන් පිඟන් ඇලවීම", "තෙල් සායම් පින්තාරු කිරීම", "කොල්කටා කෞතුකාගාරයේ සුරැකි භාරුත් කැටයම් ඉන්දීය ආඛ්‍යාන මූර්ති කලාවේ මුල් අවදිය පෙන්වයි."),
        q("මහාරාෂ්ට්‍රයේ පිහිටි 'කාර්ලේ චෛත්‍යඝරයේ' (Karle Chaitya Hall) පිවිසුම් ආලින්දයේ ඇති මූර්ති යුගලය හඳුන්වන්නේ කුමන නමින්ද?", "මිථුන රූප (Mithuna Couples)", "මකර තොරණ", "පංචනාරි ඝටය", "ත්‍රිමූර්ති රූප", "සාතවාහන යුගයේ කාර්ලේ ගල් ලෙනේ දැවැන්ත අශ්ව ලාඩමක ආරුක්කු හා අලංකාර මිථුන රූප දක්නට ඇත."),
        q("ගන්ධාර කලා සම්ප්‍රදායේ 'නිරාහාරව සිටින සිද්ධාර්ථ' (Fasting Buddha) ප්‍රතිමාවේ ඇති ප්‍රධාන ශෛලීය ලක්ෂණය කුමක්ද?", "ඇටසැකිලි හා නහර ඉල්පුණු සිරුර", "සම්පූර්ණයෙන් සුමට පිරිපුන් සිරුර", "මකරෙකු පිට වැඩ සිටීම", "රන් කබායකින් වැසී තිබීම", "ලාහෝර් කෞතුකාගාරයේ ඇති මෙම ගන්ධාර මූර්තිය දුෂ්කර ක්‍රියා අවස්ථාව අතිශය තාත්විකව දක්වයි."),
        q("මථුරා කලා සම්ප්‍රදායෙන් බිහි වූ 'කණිෂ්ක අධිරාජ්‍යයාගේ' හිස රහිත ප්‍රතිමාව ප්‍රකට වන්නේ කුමක් නිසාද?", "රාජකීය අභිමානය දක්වන පැතලි දිග කබාය හා කඩුව සහිත මූර්ති නිර්මාණය නිසා", "කාන්තා නැටුම් ඉරියව්වක් නිසා", "සුදු කිරිගරුඬින් නෙළීම නිසා", "මල් මාලාවකින් වැසී තිබීම නිසා", "රතු වැලිගලින් නෙළූ කුෂාණ රජුගේ මෙම ප්‍රතිමාව පාදමේ අක්ෂර සහිත පෞද්ගලික රාජ ප්‍රතිමාවකි."),
        q("ගුප්ත යුගයේ 'සුල්තාන්ගන්ජ් බුදු පිළිමය' (Sultanganj Buddha) නිර්මාණය කර ඇති මාධ්‍යය කුමක්ද?", "තඹ ලෝහ වාත්තුව (Copper Casting)", "මැටි පිළිස්සුම් ටෙරාකොටා", "සබන් ගල් කැටයම", "ඇත්දත් කැටයම", "වර්තමානයේ බර්මින්හැම් කෞතුකාගාරයේ ඇති මීටර් 2.3ක් උස මෙය විශාලතම ලෝහමය ඉන්දීය බුදු පිළිමයකි."),
        q("අජන්තා ලෙන් විහාර අංක 16 හි ඇති අතිශය සංවේදී බිතුසිතුවම හඳුන්වන්නේ කුමන නමින්ද?", "මියයන කුමරිය (සුන්දරීගේ ශෝකය)", "මාර පරාජය පමණි", "සීගිරි දිය කෙළිය", "ටජ් මහල් විවාහය", "නන්ද කුමරු පැවිදි වූ පුවත ඇසූ සුන්දරීගේ ශෝකජනක ක්ලාන්ත වීම මෙහි ඉතා හැඟීම්බරව ඇඳ ඇත."),
        q("අජන්තා ලෙන් විහාරවල සිතුවම් ඇඳීමේදී ගැඹුර හා වටකුරු බව (Volume) පෙන්වීමට යොදාගත් ශිල්පීය ක්‍රමය කුමක්ද?", "වර්ණ තාන හා මෘදු සෙවණැලි", "කළු රේඛාවෙන් කොටු කිරීම", "කඩදාසි තීරු ඇලවීම", "රන් කම්බි එතීම", "නාසය, පපුව හා උරහිස් ප්‍රදේශවල ලා පැහැති ආලෝක ස්පර්ශ තැබීමෙන් ත්‍රිමාණ බව මතු කර ඇත."),
        q("ඉන්දියාවේ මධ්‍යකාලීන යුගයට අයත් 'දේවගාර් හි දශාවතාර දේවාලය' වැදගත් වන්නේ කුමන හේතුවක් නිසාද?", "ශිඛර කුළුණු සහිත මුල් හින්දු දෙවොල", "ලොව පැරණිතම බෞද්ධ ස්තූපය", "පැරණි ඉස්ලාම් පල්ලියක් වීම", "විශාල දැව පැගෝඩාවක් වීම", "විෂ්ණු අනන්තශයන මූර්තිය සහිත දේවගාර් දේවාලය ගුප්ත ගෘහ නිර්මාණයේ වැදගත් සන්ධිස්ථානයකි."),
        q("ඉන්දියාවේ 'එල්ලෝරා කෛලාසනාථ දේවාලය' තැනීමේදී ශිල්පීන් අනුගමනය කළ ඉදි කිරීමේ දිශාව කුමක්ද?", "කඳු මුදුනේ සිට පහළට ගල කපා ඉවත් කරමින් නෙළීම", "පහළ සිට ගඩොල් බඳිමින් ඉහළට යාම", "දැව සැකිල්ලක් මත මැටි ගෑම", "කෑලි වෙන්ව සාදා පසුව ඇලවීම", "ටොන් ලක්ෂ ගණනක් ගල් ඉවත් කරමින් කඳු මුදුනින් අරඹා පහළට සම්පූර්ණ විහාරය නෙළා ඇත."),
        q("ඔඩීෂා ප්‍රාන්තයේ 'බුවනේශ්වර් හි ලිංගරාජ්' සහ 'පූරි ජගන්නාත්' දේවාලවල ඇති වක්‍රාකාර උස් කුළුණ හඳුන්වන්නේ කුමන නමින්ද?", "රේඛා දෙවුල් (ශිඛර කුළුණ)", "පත්තිරිප්පුව", "වටදාගෙය", "ඩෝම් අර්ධගෝලය", "උතුරු හා නැගෙනහිර ඉන්දීය කලිංග ශෛලියේ ප්‍රධාන දේවාල කුළුණු මෙසේ හැඳින්වේ."),
        q("දකුණු ඉන්දීය ද්‍රවිඩ කෝවිල් ගෘහ නිර්මාණයේ පිටත තාප්පයේ ඉදි කරන දැවැන්ත පිරමීඩාකාර පිවිසුම් දොරටුව කුමක්ද?", "ගෝපුරම් (Gopuram)", "තොරණ", "මිනාරය", "වාහල්කඩ", "මධුරෙයි මීනාක්ෂි කෝවිල වැනි දකුණු ඉන්දීය දේවාලවල දේව රූප පිරි උස් ගෝපුරම් දක්නට ලැබේ."),
        q("චෝල ලෝකඩ ප්‍රතිමා වාත්තු කිරීමේදී යොදා ගත් ඉපැරණි ක්‍රමය (Madhuchhishtha Vidhana) කුමක්ද?", "මී ඉටි ආකෘතිය මැටියෙන් වසා රත් කර ඉටි ඉවත් කර උණු ලෝහ වත් කිරීම", "ගල් කැබැල්ලක් මිටියෙන් කැඩීම", "ලෝහ තහඩු කතුරෙන් කැපීම", "මැටි පමණක් පුළුස්සා සායම් ගෑම", "පංචලෝහ මිශ්‍රණය මැකී යන ඉටි ක්‍රමයෙන් වාත්තු කර එක් එක් ප්‍රතිමාව අනන්‍ය ලෙස නිමවීය."),
        q("චීනයේ 'ටැං රාජවංශ' (Tang Dynasty) සමයේ කුඹල් කලාවේ ඉතා ජනප්‍රිය වූ තුන් වර්ණ ඔප දැමූ සෙරමික් ශෛලිය කුමක්ද?", "සැන්කායි (කොළ, කහ, දුඹුරු)", "නිල් සහ සුදු පෝසිලේන්", "කළු රතු ග්‍රීක බඳුන්", "රන්වන් මොසැයික්", "සේද මාවතේ ඔටුවන් හා අශ්ව රූප ටැං සැන්කායි ඔපයෙන් ඉතා ජීවමානව තනා ඇත."),
        q("චීන 'හැන් රාජවංශ' සමයේ අධිකාරීන්ගේ සොහොන් ගැබ්වල පමණක් නොව චිත්‍ර කලාවේදී ඉතා ගෞරවයට පාත්‍ර වූ අර්ධ වටිනා පාෂාණය කුමක්ද?", "ජේඩ් (Jade) මැණික", "ප්ලාස්ටික් රෙසිනය", "සාමාන්‍ය කළුගල", "ගල් අඟුරු", "පාරිශුද්ධත්වය හා අමරණීයත්වය සංකේතවත් කළ ජේඩ් ගලින් අතිශය සියුම් කැටයම් හා සිරුරු කවච තැනීය."),
        q("චීනයේ 'ෂැං රාජවංශ' (Shang Dynasty) සමයේ ආගමික යාගහෝම සඳහා නිපදවූ විශිෂ්ට ලෝහ කලා කෘති මොනවාද?", "ටාඕතියේ රාක්ෂ මුහුණු ලෝකඩ බඳුන්", "වීදුරු වයින් පාත්‍ර", "කැටයම් රබර් මුද්‍රා", "තෙල් සායම් ආලේඛ්‍ය", "ක්‍රි.පූ. 1500 පමණ ෂැං ලෝකඩ භාජන පුරාණ චීන ලෝහ කලාවේ ඉහළම කැටයම් නිමැවුම් පෙන්වයි."),
        q("සෝං රාජවංශ (Song Dynasty) යුගයේ චීන භූ දර්ශන සිතුවම්වල 'දුරස්ථ කඳු මුදුන්' දැක්වීම සඳහා යොදා ගත් උපක්‍රමය කුමක්ද?", "ලා දියාරු තීන්ත හා මීදුම් අවකාශ", "තද කළු බෝඩරයක් ඇඳීම", "දීප්තිමත් රතු රේඛා ඇඳීම", "කඳු මත අංක ලිවීම", "පසුබිම් කඳු ළා වර්ණයෙන්ද ඉදිරි පඳුරු තද කළු පින්සල් පහරින්ද ඇඳ ගැඹුර මවා පායි."),
        q("සම්ප්‍රදායික චීන චිත්‍ර කලාවේ සංචාරකයෙකු මෙන් කඩදාසි රෝල (Handscroll) නරඹන්නේ කෙසේද?", "දකුණේ සිට වමට ක්‍රමයෙන් දිගහරිමින් කොටසින් කොටස නැරඹීම", "වමේ සිට දකුණට බිත්තියේ ඇණ ගසා බැලීම", "පහළ සිට ඉහළට විද්‍යුත් තිරයකින් බැලීම", "කෑලිවලට කපා පොතක ඇලවීම", "දිගැති තිරස් රෝල් චිත්‍ර මේසය මත කොටසින් කොටස විවෘත කරමින් රසවිඳීම චීන චාරිත්‍රයයි."),
        q("ජපානයේ 'ටෝරි' (Torii) යනුවෙන් හැඳින්වෙන සම්ප්‍රදායික රතු පැහැති ද්වි-බාල්ක දොරටුව අයත් වන්නේ කුමන ආගමික වාස්තු කලාවටද?", "ෂින්ටෝ (Shinto) පූජනීය දේවස්ථාන වාස්තු කලාවට", "ග්‍රීක කෝවිල්වලට", "රෝම නාට්‍යශාලාවලට", "මිසර සොහොන් ගැබ්වලට", "සාමාන්‍ය ලෝකයෙන් පූජනීය අවකාශයට පිවිසෙන දොරටුව ලෙස ෂින්ටෝ ටෝරි ගේට්ටු ඉදි කරයි."),
        q("ජපානයේ නාරා නගරයේ තෝදායි-ජි විහාරයේ ඇති 'දයිබුත්සු' (Daibutsu) ප්‍රතිමාව කුමක්ද?", "විශාල ලෝකඩ වෛරෝචන හිඳි බුදු පිළිමය", "කුඩා දැව සෙල්ලම් බඩුවක්", "රන් කඩුවක්", "මැටි පහනක්", "8 වන සියවසේ ඉදි කළ මෙය ලොව විශාලතම ලෝකඩ බුදු පිළිම හා දැව ගොඩනැගිලිවලින් එකකි."),
        q("ජපන් චිත්‍ර කලාවේ 'බියෝබු' (Byobu) යනුවෙන් හැඳින්වෙන විශේෂිත කලා නිර්මාණය කුමක්ද?", "රන් පත්‍ර සිතුවම් නැමෙන තිර", "මැටි පිඟන් සැරසිලි", "දැව වෙස්මුහුණු", "ලෝහ කාසි", "පැනල් කිහිපයකින් සමන්විත නැමෙන තිර මත ගස්, මල් හා කඳු අලංකාරව සිතුවම් කෙරේ."),
        q("ජපන් 'නෝ' (Noh) සම්භාව්‍ය නාට්‍ය කලාව හා බැඳුණු ඉතා සියුම් මූර්ති කලාංගය කුමක්ද?", "සයිප්‍රස් දැව නෝ වෙස්මුහුණු", "ප්ලාස්ටික් හිස්වැසුම්", "යකඩ සන්නාහ", "වීදුරු කණ්ණාඩි", "හිස හරවන කෝණය අනුව දුක හෝ සතුට වෙනස් වී පෙනෙන සේ නෝ වෙස්මුහුණු කැටයම් කර ඇත."),
        q("ජපානයේ සාම්ප්‍රදායික මල් සැරසිලි කලාව හෙවත් ස්වභාවධර්මයේ සරල රේඛීය සංයුතිය ගොඩනගන කලාව කුමක්ද?", "ඉකෙබානා (Ikebana)", "කබුකි", "සුමෝ", "ටෙරාකොටා", "අහස, පොළොව සහ මිනිසා සංකේතවත් කරන ත්‍රිකෝණාකාර පරතරයකින් මල් හා අතු සැකසීම ඉකෙබානා වේ."),
        q("ඉන්දියාවේ භූගත ජල කළමනාකරණය හා ජ්‍යාමිතික වාස්තු කලාව එක් කළ ගුජරාට් හා රාජස්ථානයේ විස්මිත නිර්මාණ මොනවාද?", "පඩිපෙළ ළිං (රාණි කි වාව්)", "උස් ගුවන් පාලම්", "සඳකඩපහණ්", "විශාල ලෝහ ටැංකි", "මහල් කිහිපයක් පොළොව යටට පඩි හා දේව මූර්ති සහිතව තැනූ පඩිපෙළ ළිං ලෝක උරුම කලා නිර්මාණ වේ."),
        q("ඉන්දියාවේ 'නාලන්දා' හා 'පාල' (Pala) රාජවංශ යුගයේ (ක්‍රි.ව. 8–12 සියවස්) නිපදවූ බෞද්ධ මූර්තිවල විශේෂ ලක්ෂණය කුමක්ද?", "කළු බැසෝල්ට් හා ලෝකඩ ප්‍රතිමා", "සුදු කපු රෙදි බෝනික්කන්", "රතු මැටි කුට්ටි", "ග්‍රීක කිරිගරුඬ රූප", "කළු ගල ලෝහයක් මෙන් සියුම්ව කැටයම් කිරීම හා තල් කොළ පුස්කොළ පොත් චිත්‍ර පාල යුගයේ ප්‍රකටය."),
        q("ඉන්දියාවේ හම්පි (Hampi) නගරයේ ඉදි වූ විජයනගර අධිරාජ්‍යයේ (ක්‍රි.ව. 14–16 සියවස්) ප්‍රසිද්ධ ශිලා කලා නිර්මාණය කුමක්ද?", "විත්තල ගල් රථය හා කුළුණු", "සාංචි තොරණ", "බරාබර් ලෙන්", "හරප්පා මුද්‍රා", "තට්ටු කළ විට සංගීත ස්වර නිකුත් කරන කුළුණු සහිත විජයනගර ශෛලිය ලංකාවේ ගඩලාදෙණියටද බලපෑවේය."),
        q("ගන්ධාර සහ මථුරා බුදු පිළිම දෙකේම 'හිස පිටුපස' දක්නට ලැබෙන රැස් වළල්ල හඳුන්වන්නේ කුමන නමින්ද?", "ප්‍රභාමණ්ඩලය (Halo / Nimbus)", "සිරස්පත", "ඌර්ණ රෝමය", "උෂ්ණීෂය", "බුදුන් වහන්සේගේ දිව්‍යමය ප්‍රභාව දැක්වීමට ගන්ධාරයේ චාම්වද මථුරාවේ මල් කැටයමින්ද රැස් වළල්ල යෙදේ."),
        q("බුදු පිළිමයක නළල මැද ඇති කුඩා රවුම් සලකුණ හා හිස මුදුනේ ඇති ගැටය හඳුන්වන්නේ පිළිවෙලින් කවර නම්වලින්ද?", "ඌර්ණ රෝමය සහ උෂ්ණීෂය", "අභය මුද්‍රාව සහ ධ්‍යාන මුද්‍රාව", "පද්මාසනය සහ වීරාසනය", "සිවුර සහ පාත්‍රය", "මහා පුරුෂ ලක්ෂණ අනුව නළල මැද ඌර්ණ රෝම ධාතුවද හිස මුදුනේ ප්‍රඥා උෂ්ණීෂයද නෙළනු ලැබේ."),
        q("ඉන්දියාවේ සමකාලීන ජාතික කලා පුනරුදය (Bengal School of Art) ආරම්භ කළ 20 වන සියවසේ මුල් පුරෝගාමී ශිල්පියා කවුද?", "අබනීන්ද්‍රනාත් තාගෝර්", "පැබ්ලෝ පිකාසෝ", "ලියනාඩෝ ඩා වින්චි", "කත්සුෂිකා හොකුසායි", "බටහිර ඇකඩමික් ක්‍රමයෙන් මිදී අජන්තා, මෝගල් හා ජපන් වෝෂ් ශිල්පය එක් කර බෙංගාල ගුරුකුලය පිහිටුවීය."),
        q("අබනීන්ද්‍රනාත් තාගෝර් විසින් 1905 දී නිර්මාණය කළ ඉන්දීය නිදහස් හැඟීම දනවන ජල සායම් සිතුවම කුමක්ද?", "භාරත මාතා (Bharat Mata)", "මොනාලිසා", "ගුවර්නිකා", "තාරකා රාත්‍රිය", "කහ වස්ත්‍ර හැඳ සිව් අතින් වරදාන දරන භාරත මාතා සිතුවම ඉන්දීය නූතන ජාතික කලාවේ සංකේතයකි."),
        q("ඉන්දියාවේ ශාන්තිනිකේතන් කලා ආයතනය හරහා දේශීය හා ආසියාතික කලා පුහුණුව ලංකාවේ කලාකරුවන්ටද බලපෑම් කළ මූර්ති හා චිත්‍ර ආචාර්යවරයා කවුද?", "නන්දලාල් බෝස් (Nandalal Bose)", "සැල්වදෝර් ඩාලි", "මයිකල් ආන්ජලෝ", "රෙම්බ්‍රාන්ට්", "ඉන්දීය ව්‍යවස්ථාවේ පිටපත පවා සිතුවමින් සැරසූ නන්දලාල් බෝස් ලාංකේය ශිල්පීන්ටද ගුරු විය."),
        q("ඉන්දීය ගෘහ නිර්මාණයේ 'ආරාමික කලා ශිල්පියෙකු' ලෙස ප්‍රකට වූ ටිබෙට්-නේපාල 'තංකා' (Thangka) චිත්‍ර කලාවේ ප්‍රධාන මාධ්‍යය කුමක්ද?", "රෙදි මත ඇඳ එල්ලන මණ්ඩල", "කළුගලින් පමණක් නෙළීම", "තහඩු මත ඇසිඩ් කෙටීම", "මැටි බඳුන් පිළිස්සීම", "රෝල් කර රැගෙන යා හැකි බෞද්ධ භාවනා සිතුවම් තංකා ලෙස හිමාලයානු කලාපයේ ප්‍රකටය."),
        q("කාම්බෝජයේ අංකෝර් තොම් (Angkor Thom) නගරයේ ඇති 'බයොන් දේවාලයේ' (Bayon Temple) අද්විතීය වාස්තු මූර්ති අංගය කුමක්ද?", "සිව් දිසා මුහුණු 216 කුළුණු", "සිංහ රූප හතරක් පමණක්", "වීදුරු පිරමීඩයක් තිබීම", "දැවමය පැගෝඩා හතක්", "අවලෝකිතේශ්වර බෝධිසත්ව හෝ සත්වන ජයවර්මන් රජුගේ ශාන්ත මුහුණු කුළුණු සෑම පැත්තකින්ම පෙනේ."),
        q("ඉන්දුනීසියාවේ බෝරෝබුදූර් ස්තූපයේ ඉහළම වෘත්තාකාර මළු තුනේ (Arupadhatu) ඇති ඝණ්ටාකාර ගල් කූඩු තුළ තැන්පත් කර ඇත්තේ කුමක්ද?", "ධ්‍යානි බුදු පිළිම", "රන් කාසි ගබඩා", "රාජකීය අවි ආයුධ", "මැටි පහන්", "සිදුරු සහිත කුඩා ස්තූප (Stupikas) 72ක් තුළ වැඩ සිටින බුදු පිළිම නිර්වාණ මාර්ගය සංකේතවත් කරයි."),
        q("පකිස්තානයේ තිබූ බාමියන් මිටියාවතට නුදුරු ඇෆ්ගනිස්ථානයේ හා මධ්‍යම ආසියාවේ බෞද්ධ මූර්ති හා ලෙන් කලාව හැඳින්වෙන්නේ කුමන සම්ප්‍රදායට අයත් ලෙසද?", "ගන්ධාර සම්ප්‍රදායේ උතුරු ව්‍යාප්තිය ලෙස", "චෝල සම්ප්‍රදාය ලෙස", "මහනුවර සම්ප්‍රදාය ලෙස", "ජපන් සෙන් සම්ප්‍රදාය ලෙස", "විනාශ කරන ලද දැවැන්ත බාමියන් හිටි බුදු පිළිම ගන්ධාර හා ගුප්ත ආභාසය ලැබූ මහා කලා කෘති විය."),
        q("ඉන්දියාවේ සුප්‍රකට 'බාග් ලෙන්' (Bagh Caves) සහ 'සිත්තනවාසල්' (Sittanavasal) ලෙන් සිතුවම් අයත් වන්නේ කුමන චිත්‍ර පරපුරටද?", "අජන්තා සම්භාව්‍ය බිතුසිතුවම් ආරට", "මහනුවර උඩරට සම්ප්‍රදායට", "පුනරුද තෙල් සායම් සම්ප්‍රදායට", "නූතන ඩිජිටල් කලාවට", "තමිල්නාඩුවේ ජෛන සිත්තනවාසල් නෙළුම් පොකුණ හා මධ්‍ය ප්‍රදේශ් බාග් සිතුවම් අජන්තා ආර අනුව යයි."),
        q("ඉන්දීය මූර්ති හා චිත්‍ර කලාවේදී 'නවරස' (Nine Rasas) යන සෞන්දර්ය සංකල්පයෙන් අදහස් කරන්නේ කුමක්ද?", "කෘතියෙන් ජනිත වන රස නවය", "වර්ණ නවයක මිශ්‍රණයක්", "ගොඩනැගිලි මහල් නවයක්", "පින්සල් ප්‍රමාණ නවයක්", "භරතමුනිගේ නාට්‍යශාස්ත්‍රය අනුව භාරතීය හා ලාංකේය කලාවේ භාව ප්‍රකාශනය රස සිද්ධාන්තය මත පදනම් වේ."),
        q("ජපානයේ 'සුමි-ඒ' (Sumi-e) චිත්‍ර ශිල්පියෙකු උණ ගසක් හෝ කුරුල්ලෙකු අඳින විට අවධාරණය කරන ප්‍රධාන ගුණාංගය කුමක්ද?", "පින්සල් පහර කිහිපයකින් සාරය දැක්වීම", "සෑම කොළයකම නහර පැය ගණනක් ඇඳීම", "වර්ණ විස්සක් එක මත ගෑම", "කැන්වසයේ හිස් තැනක් නොතැබීම", "අවම පින්සල් පහරින් උපරිම සජීවී බව මැවීම සෙන් කලාවේ හා සුමි-ඒ ශිල්පයේ හරයයි."),
        q("චීන චිත්‍ර කලාවේ 'වං වෙයි' (Wang Wei) හා 'ගු කයිචි' (Gu Kaizhi) වැනි ආචාර්යවරුන් ප්‍රසිද්ධ වූයේ කුමන සිද්ධාන්ත සඳහාද?", "මොනොක්‍රෝම් කාව්‍යමය භූ දර්ශන", "ලෝහ කාලතුවක්කු වාත්තු කිරීම", "වීදුරු කැඩපත් තැනීම", "පුනරුද ගණිත න්‍යාය", "කවියක් තුළ සිතුවමත් සිතුවමක් තුළ කවියත් ඇතැයි පෙන්වූ ටැං යුගයේ වං වෙයි ඉතා ප්‍රකටය."),
        q("ජපානයේ හෝකුසායිගේ 'කනගාවා මහා රළ පහර' නිර්මාණයේදී යොදාගෙන ඇති කැපී පෙනෙන යුරෝපීය වර්ණකය කුමක්ද?", "ප්‍රශියන් නිල් (Prussian Blue)", "ගොකටු කහ", "සාදිලිංගම් රතු", "මකුළු මැටි සුදු", "ලන්දේසි වෙළෙඳුන් හරහා ජපානයට ආ ප්‍රශියන් නිල් වර්ණය ජපන් මුද්‍රණවල ගැඹුර මැවීමට යොදා ගත්හ."),
        q("ඉන්දු නිම්න ශිෂ්ටාචාරයේ 'රතු හා කළු මැටි බඳුන්' (Painted Pottery) මත සිතුවම් කර තිබූ ප්‍රධාන මෝස්තර මොනවාද?", "ජ්‍යාමිතික රටා, වෘත්ත, පීපල් කොළ, මසුන් හා මොනරුන්", "රාජකීය යුද සිතියම්", "බුදු සිරිතේ ජාතක කතා", "ලතින් අක්ෂර මාලාව", "කුඹල් සකපෝරුවෙන් සෑදූ රතු පසුබිම් මැටි බඳුන් මත කළු තීන්තෙන් මෙම රටා ඇඳ පුළුස්සා ඇත."),
        q("ඉන්දියාවේ මෞර්ය යුගයේ 'විදිශා හි හෙලියෝඩෝරස් කුළුණ' හා 'ලෝමස් රිෂි ලෙන' කුමන වාස්තු ඉතිහාසයක් හෙළි කරයිද?", "දැව වාස්තු ආකෘති ගලට නැගීම", "වීදුරු ගොඩනැගිලි තාක්ෂණය", "යකඩ පාලම් තාක්ෂණය", "මුහුදු යට උමං මාර්ග", "ලෝමස් රිෂි ලෙන් දොරටුව දැවමය පියස්සක් හා බාල්ක අනුකරණය කර ගලෙන් කපා ඇත."),
        q("මහාරාෂ්ට්‍රයේ 'භාජා' (Bhaja) සහ 'බෙඩ්සා' (Bedsa) ලෙන් කලාව අයත් වන්නේ ඉන්දීය බෞද්ධ කලාවේ කුමන යුගයටද?", "ක්‍රි.පූ. 2–1 සියවස්වල මුල් හීනයාන ගල් ලෙන් යුගයට", "ක්‍රි.ව. 18 වන සියවසට", "මෝගල් අධිරාජ්‍ය යුගයට", "බ්‍රිතාන්‍ය යුගයට", "ලී පරාල ක්‍රමය අනුකරණය කළ මුල් කාලීන චෛත්‍යඝර ලෙන් භාජා හා කොණ්ඩානේහි දක්නට ලැබේ."),
        q("මථුරා හා ගන්ධාර කලා ගුරුකුලවල නිපදවූ බුදු පිළිමවල දකුණු අත උරහිස මට්ටමට ඔසවා අත්ල ඉදිරියට පෙන්වන මුද්‍රාව කුමක්ද?", "අභය මුද්‍රාව (ආරක්ෂාව)", "භූමිස්පර්ශ මුද්‍රාව", "ධ්‍යාන මුද්‍රාව", "වරද මුද්‍රාව", "බිය දුරු කරන සංකේතය වන අභය මුද්‍රාව මුල් කුෂාණ බුදු පිළිමවල ඉතා බහුලව යෙදේ."),
        q("චීනයේ 'මහා ප්‍රාකාරය' (Great Wall) හැරුණු විට බෞද්ධ මූර්ති කලාව අතින් විශිෂ්ට වන උතුරු චීනයේ ලෙන් දෙකක් මොනවාද?", "යුන්ගැං (Yungang) සහ ලෝංමෙන් (Longmen) ලෙන්", "සීගිරි සහ දඹුලු ලෙන්", "එලිෆන්ටා සහ කාර්ලේ ලෙන්", "බරාබර් සහ බාග් ලෙන්", "උතුරු වෙයි හා ටැං රාජවංශ සමයේ කඳු බිත්තිවල දැවැන්ත ශිලා බුදු පිළිම නෙළා ඇත."),
        q("චීන කලා සම්ප්‍රදායේ 'වකුගඩු හැඩැති හෝ කෙටි තියුණු පහරින්' පර්වත හා ගස්වල මතුපිට ස්වභාවය (Texture) දක්වන ක්‍රමය කුමක්ද?", "කුන් (Cun - Brush Texture Strokes)", "පොයින්ටිලිසම්", "සිල්ක් ස්ක්‍රීන්", "කොලාජ්", "හෙම්ප් කෙඳි පහර, පොරෝ පහර ආදී විවිධ පින්සල් පහරවලින් චීන කලාකරුවෝ පර්වත මතුපිට පෙන්වූහ."),
        q("ජපානයේ සාම්ප්‍රදායික 'ගෙයිෂා හා කබුකි' නළුවන්ගේ චිත්‍ර මෙන්ම භූ දර්ශන ලී මුද්‍රණයෙන් ජනප්‍රිය කළ 18 වන සියවසේ ශිල්පියෙකු කවුද?", "කිටගාවා උටමාරෝ හා ෂරාකු", "රැෆායෙල් සන්සියෝ", "ජොටෝ ඩි බොන්ඩෝනේ", "ඇන්ඩි වෝහෝල්", "උටමාරෝගේ ස්ත්‍රී ආලේඛ්‍ය හා ෂරාකුගේ කබුකි නළු මුද්‍රණ උකියෝ-ඒ කලාවේ ඉහළම කෘති වේ."),
        q("දකුණු ඉන්දියාවේ මහබලිපුරම් හි 'වෙරළ දේවාලය' (Shore Temple) නිර්මාණය කර ඇති ගල් වර්ගය හා යුගය කුමක්ද?", "පල්ලව යුගයේ කැටයම් කළ කළුගල් කුට්ටි (Granite) ඉදිකිරීමකි", "මෞර්ය යුගයේ දැව ඉදිකිරීමකි", "මෝගල් යුගයේ ගඩොල් මාලිගාවකි", "චෝල යුගයේ ලෝකඩ ගොඩනැගිල්ලකි", "බෙංගාල බොක්ක අසල තැන්පත් කළ ග්‍රැනයිට් ගල් කුට්ටිවලින් තැනූ මුල්ම ද්‍රවිඩ ව්‍යුහාත්මක දේවාලයයි."),
        q("චීන හා ජපන් කලාවේ 'වක්‍රාකාර උඩට නැමුණු පියස්ස' (Curved Eaves / Pagoda Roof) නිර්මාණය කිරීමේ කලාත්මක හා ප්‍රායෝගික අරමුණ කුමක්ද?", "වැසි දිය බැසීම හා සැහැල්ලු පෙනුම", "හිම මිදී වහලය කඩා වැටීමට", "පක්ෂීන්ට කූඩු තැනීම වැළැක්වීමට", "ගොඩනැගිල්ල අඳුරු කිරීමට", "බෞද්ධ ස්තූප ආකෘතිය චීන මුර කුළුණු සමඟ එක් වීමෙන් පැගෝඩා නැමුණු වහල බිහිවිය."),
        q("ශ්‍රී ලංකාවේ බිතුසිතුවම් හා මූර්ති ඉතිහාසය හදාරන සිසුවෙකු ඉන්දියාවේ 'අජන්තා, අමරාවතී සහ පල්ලව' කලාවන් ඉගෙන ගත යුත්තේ ඇයි?", "ආසියානු කලා ප්‍රවාහ සමඟ බැඳි නිසා", "ලාංකේය කලාව සම්පූර්ණ පිටපතක් නිසා", "විභාගයට ඉංග්‍රීසි ලිවීමට පමණක්", "බටහිර කලාව තහනම් නිසා", "ආසියාතික ආභාසය ලබමින්ම සිංහල කලාකරුවා දේශීය අනන්‍යතාවක් ගොඩනැගූ ආකාරය ඉන් වටහාගත හැකිය."),
        q("මෝගල් චිත්‍ර ශිල්පයේ සතුන් හා පක්ෂීන් අතිශය ස්වභාවික විද්‍යාත්මක නිරීක්ෂණයෙන් යුතුව සිතුවම් කළ ප්‍රකට ශිල්පියා කවුද?", "උස්තාද් මන්සූර් (Ustad Mansur)", "අබනීන්ද්‍රනාත් තාගෝර්", "හොකුසායි", "ජෝර්ජ් කීට්", "ජහන්ගීර් අධිරාජ්‍යයාගේ රාජ සභාවේ සිටි උස්තාද් මන්සූර් සීබ්‍රා, තුර්කි කුකුළා හා මල් සියුම්ව ඇන්දේය."),
        q("ඉන්දියාවේ හින්දු හා බෞද්ධ වාස්තු කලාවේදී 'මණ්ඩපය' සහ 'ගර්භගෘහය' යනුවෙන් හඳුන්වන්නේ කුමන කොටස්ද?", "මණ්ඩපය ශාලාවයි, ගර්භගෘහය කුටියයි", "මණ්ඩපය වහලයයි, ගර්භගෘහය වැටයි", "මණ්ඩපය හා ගර්භගෘහය භූගත ළිං වේ", "මණ්ඩපය රථයයි, ගර්භගෘහය ගේට්ටුවයි", "භාරතීය හා ලාංකේය පිළිමගෙවල්වල පූජනීය ප්‍රතිමාව ඇති අභ්‍යන්තර කුටිය ගර්භගෘහය ලෙස හැඳින්වේ."),
        q("පෙරදිග ආසියාතික කලාවේ චීන හා ජපන් සිතුවම්වල 'අසමමිතික සමතුලිතතාව' (Asymmetrical Balance) ගොඩනගන්නේ කෙසේද?", "එක් පසෙක අඳුර හා අනෙක් පස හිස් බව", "දෙපසම සමාන ඡායාරූප දෙකක් ඇඳීම", "මැද රේඛාවක් ගසා කොටු බෙදීම", "හතරැස් රාමුවක සිර කිරීම", "භාරය හා හිස් අවකාශය අතර සියුම් තුලනය පෙරදිග කලාවට නිසල සුන්දරත්වයක් ගෙන දෙයි."),
        q("ඉන්දියාවේ මෞර්ය, ගුප්ත, චෝල හා මෝගල් කලා යුග පිළිවෙළින් නිවැරදි කාලානුක්‍රමයට දැක්වෙන පිළිතුර කුමක්ද?", "මෞර්ය → ගුප්ත → චෝල → මෝගල්", "මෝගල් → චෝල → ගුප්ත → මෞර්ය", "චෝල → මෞර්ය → මෝගල් → ගුප්ත", "ගුප්ත → මෝගල් → මෞර්ය → චෝල", "ක්‍රි.පූ. 3 සියවසේ මෞර්ය, 4–6 සියවස්වල ගුප්ත, 10–12 සියවස්වල චෝල හා 16–18 සියවස්වල මෝගල් යුග පැවතිණි.")
    )
}
